const token = (n = 32) => Array.from({ length: n }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');

// Same fields whether the client came from the form or a webhook (CRM, Stripe, Zapier...)
const out = [];
for (const item of $input.all()) {
  const isHook = item.json.body && typeof item.json.body === 'object';
  const j = isHook ? item.json.body : item.json;
  const g = k => String(j[k] ?? '').trim();
  const name = g('contact_name') || g('name');
  const email = g('email').toLowerCase();
  out.push({ json: { contact_name: name, company: g('company') || name, email, phone: g('phone'), package: g('package') || 'Standard',
    start_date: g('start_date') || $now.toFormat('yyyy-MM-dd'), value: Number(g('value')) || '', account_manager: g('account_manager').toLowerCase(),
    notes: g('notes').slice(0, 2000), source: isHook ? 'webhook' : 'form',
    client_id: 'CL-' + $now.toFormat('yyMMdd') + '-' + token(4).toUpperCase(), token: token(24) } });
}
return out;

// Stop on missing details or a client that is already onboarding (same e-mail)
const S = $('Set onboarding settings').first().json;
const c = $('Add client ID').first().json;
const existing = $('Read existing clients').all().map(i => i.json).filter(r => r.client_id);
const problems = [];
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email)) problems.push('a valid client e-mail is missing');
if (!c.contact_name) problems.push('the contact name is missing');
const dup = existing.find(r => String(r.email).toLowerCase() === c.email && String(r.stage) !== 'closed');
if (dup) problems.push(`${c.email} is already a client (${dup.client_id}, ${dup.company}, stage ${dup.stage})`);
const folder_name = `${c.company} (${DateTime.fromISO(c.start_date).isValid ? DateTime.fromISO(c.start_date).toFormat('yyyy-MM') : $now.toFormat('yyyy-MM')})`;
return [{ json: { ...c, ready: problems.length === 0, problems: problems.join('; '), folder_name } }];

// Everything the e-mails, the CRM row and the kickoff links need, in one item
const S = $('Set onboarding settings').first().json;
const c = $('Check details and duplicates').first().json;
const folder = $('Create client folder').first().json;
const names = $('List subfolders').all().map(i => i.json.folder_name);
const subs = $('Create subfolder').all().map((i, k) => ({ id: i.json.id, name: names[k] || i.json.name }));
const kw = String(S.assets_folder_keyword || 'assets').toLowerCase();
const assets = subs.find(f => String(f.name).toLowerCase().includes(kw)) || { id: folder.id };
let docs = [];
try { docs = $('Copy template document').all().map(i => i.json).filter(d => d.id).map(d => ({ name: d.name, url: `https://docs.google.com/document/d/${d.id}/edit` })); } catch (e) {}
const base = String(S.n8n_base_url || '').replace(/\/$/, '');
return [{ json: { ...c, folder_id: folder.id, folder_url: `https://drive.google.com/drive/folders/${folder.id}`,
  assets_folder_id: assets.id, assets_url: `https://drive.google.com/drive/folders/${assets.id}`,
  docs_list: docs.map(d => `${d.name}: ${d.url}`).join('\n'), docs,
  intake_url: `${base}/form/client-intake?client_id=${encodeURIComponent(c.client_id)}` } }];

const c = $('Collect onboarding links').first().json;
return [{ json: { client_id: c.client_id, created: $now.toFormat('yyyy-MM-dd HH:mm'), company: c.company, contact_name: c.contact_name,
  email: c.email, phone: c.phone, package: c.package, value: c.value, start_date: c.start_date, account_manager: c.account_manager || '',
  folder_id: c.folder_id, folder_url: c.folder_url, assets_url: c.assets_url, intake_url: c.intake_url, token: c.token,
  stage: 'onboarding', intake_status: 'sent', intake_received: '', intake_summary: '', reminders: 0, last_reminder: '', kickoff: '',
  notes: c.notes } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Welcome e-mail: intake form, shared folder, kickoff slots (or a reply-with-times fallback)
const S = $('Set onboarding settings').first().json;
const c = $('Collect onboarding links').first().json;
const btn = (url, label) => `<a href="${url}" style="display:inline-block;margin:4px 6px 4px 0;padding:9px 14px;border-radius:6px;background:#1f6feb;color:#fff;text-decoration:none">${esc(label)}</a>`;
const first = esc(String(c.contact_name).split(' ')[0] || 'there');
const slots = (c.slots || []).length
  ? `<br>${c.slots.map(s => btn(s.url, s.label)).join('')}<br><small>None of these work? Reply with two or three times that suit you.</small>`
  : ' Reply with two or three times that suit you and we will send an invite.';
const docs = (c.docs || []).length ? `<li><b>Your documents</b>: ${c.docs.map(d => `<a href="${d.url}">${esc(d.name)}</a>`).join(', ')}</li>` : '';
const html = `<p>Hi ${first},</p>
<p>Welcome to ${esc(S.agency_name)}! We are looking forward to getting started with ${esc(c.company)}. Three quick things for a smooth start:</p>
<ol><li><b>Tell us about your goals</b> (about 10 minutes): ${btn(c.intake_url, 'Open the intake form')}</li>
<li><b>Share your files</b>: logos, brand guidelines and anything useful go in <a href="${c.assets_url}">your shared folder</a>.</li>
<li><b>Pick a kickoff call</b> (${Number(S.kickoff_minutes) || 45} minutes, video):${slots}</li>${docs}</ol>
<p>Start date: <b>${esc(c.start_date)}</b>${c.package ? ` · Package: ${esc(c.package)}` : ''}. Any questions, just reply to this e-mail.</p>
<p>${esc(S.your_name)}<br>${esc(S.agency_name)}</p>`;
return [{ json: { to: c.email, subject: `Welcome to ${S.agency_name}: your next steps`, html } }];

// Intake answers + the matching client row (works without a match too)
const f = $('Client intake form').first().json;
const id = String(f.client_id || f.formQueryParameters?.client_id || '').trim();
const client = $('Find client for intake').all().map(i => i.json).find(r => r.client_id && String(r.client_id) === id) || {};
const labels = { company: 'Company', goals: 'Goals', audience: 'Audience / customers', examples: 'Competitors or examples they like',
  brand_assets: 'Brand assets', access_needed: 'Accounts we need access to', contacts: 'Key contacts and approvals', deadlines: 'Deadlines', other: 'Anything else' };
const answers = {};
for (const k of Object.keys(labels)) answers[k] = String(f[k] ?? '').trim().slice(0, 3000);
const answers_text = Object.entries(labels).map(([k, l]) => `${l}: ${answers[k] || '(not answered)'}`).join('\n');
return [{ json: { client_id: id, client, matched: !!client.client_id, answers, answers_text } }];

const p = $('Prepare intake answers').first().json;
const o = $('Summarise intake with AI').first().json.output || {};
const li = a => (a || []).map(x => '- ' + x).join('
');
const text = `${o.summary || ''}

Goals:
${li(o.goals)}

Audience: ${o.audience || '-'}

Deliverables mentioned:
${li(o.deliverables_mentioned)}

Deadlines:
${li(o.deadlines)}

Risks and gaps:
${li(o.risks_or_gaps)}

Questions for the kickoff:
${li(o.questions_for_kickoff)}

First actions:
${li(o.first_actions)}

Urgency: ${o.urgency || 'normal'}`;
return [{ json: { update: { client_id: p.client_id, intake_status: 'received', intake_received: $now.toFormat('yyyy-MM-dd HH:mm'),
  intake_summary: String(o.summary || '').slice(0, 1000) }, summary_text: text, raw_answers: p.answers_text, matched: p.matched,
  company: p.client.company || p.answers.company || 'Unknown client', folder_id: p.client.folder_id || '', folder_url: p.client.folder_url || '',
  account_manager: p.client.account_manager || '', urgency: o.urgency || 'normal' } }];
